<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import client from '../api/client'
import TorzsadatModal from '../components/TorzsadatModal.vue'
import ZoldsegModal from '../components/ZoldsegModal.vue'
import Gyorskereso from '../components/Gyorskereso.vue'

const items=ref([]),keszlet=ref([]),vevek=ref([]),zoldsegek=ref([]),rekesztipusok=ref([])
const hiba=ref(''),betolt=ref(true),datum=ref(today()),keres=ref('')
const showVevoModal=ref(false),showZoldsegModal=ref(false),showRekeszModal=ref(false),showEladasModal=ref(false),showDetailModal=ref(false),showAtvitelModal=ref(false)
const selectedStock=ref(null),detailItem=ref(null),editId=ref(null),editForm=ref({}),editField=ref(null)
const atvitelStock=ref(null),atvitelForm=ref({celDatum:'',mennyiseg:1}),atvitelHiba=ref('')
const form=ref({vevoId:'',zoldsegId:'',rekeszTipusId:'',mennyiseg:1,egysegar:'',fizetve:false,elvitte:false,visszahozottDb:0,hianyFizettDb:0,megjegyzes:''})
const arSzerkesztes=ref(false),gyorsArak=ref(['','',''])
const GYORS_AR_STORAGE='zoldpiac:gyors-arak:v1'
function today(){return new Date().toISOString().slice(0,10)}
function holnap(d){const x=new Date(d+'T00:00:00');x.setDate(x.getDate()+1);return x.toISOString().slice(0,10)}
function fmtDate(d){return new Date(d+'T00:00:00').toLocaleDateString('hu-HU')}
function fmtIdo(d){return new Date(d).toLocaleTimeString('hu-HU',{hour:'2-digit',minute:'2-digit'})}
function clampDigits(v,n){const d=String(v??'').replace(/[^0-9]/g,'').slice(0,n);return d===''?'':Number(d)}
function vevoCimke(v){return `${v.nev||'(névtelen)'}${v.megjegyzes?' — '+v.megjegyzes:''}`}
function vevoLetrehozva(v){vevek.value.push(v)}
const apiRoot=client.defaults.baseURL.replace(/\/api\/?$/,'')
function zoldsegKep(id){const z=zoldsegek.value.find(x=>x.id===id);if(!z?.kepUrl)return null;return z.kepUrl.startsWith('http')?z.kepUrl:apiRoot+z.kepUrl}
function csempeStilus(stock){const u=zoldsegKep(stock.zoldsegId);return u?{backgroundImage:`url('${u}')`,backgroundSize:'cover',backgroundPosition:'center'}:{}}
function betoltArak(zoldsegId){try{const all=JSON.parse(localStorage.getItem(GYORS_AR_STORAGE)||'{}');const a=all[String(zoldsegId)];gyorsArak.value=Array.isArray(a)?[a[0]??'',a[1]??'',a[2]??'']:['','','']}catch{gyorsArak.value=['','','']};arSzerkesztes.value=false}
function mentesArak(){if(!form.value.zoldsegId)return;try{const all=JSON.parse(localStorage.getItem(GYORS_AR_STORAGE)||'{}');all[String(form.value.zoldsegId)]=gyorsArak.value.map(v=>v===''?'':Number(v));localStorage.setItem(GYORS_AR_STORAGE,JSON.stringify(all));arSzerkesztes.value=false}catch{hiba.value='A gyorsárak mentése sikertelen.'}}
function gyorsArBeallit(v){if(!arSzerkesztes.value&&v!=='')form.value.egysegar=Number(v)}
async function torzsadatok(){try{const[v,z,r]=await Promise.all([client.get('/vevek'),client.get('/zoldsegek'),client.get('/rekesztipusok')]);vevek.value=v.data;zoldsegek.value=z.data;rekesztipusok.value=r.data}catch{hiba.value='Nem sikerült betölteni a törzsadatokat.'}}
async function frissit(){betolt.value=true;hiba.value='';try{const params={datum:datum.value};if(keres.value.trim())params.q=keres.value.trim();const[e,k]=await Promise.all([client.get('/eladas',{params}),client.get('/riportok/keszlet',{params:{datum:datum.value}})]);items.value=e.data;keszlet.value=k.data.filter(x=>x.kocsinMaradt>0)}catch{hiba.value='Nem sikerült betölteni az eladásokat vagy a kocsi készletét.'}finally{betolt.value=false}}
onMounted(async()=>{await torzsadatok();await frissit()});watch([datum,keres],frissit)
watch(()=>form.value.zoldsegId,id=>{const z=zoldsegek.value.find(x=>x.id===Number(id));if(z?.alapertelmezettRekeszTipusId)form.value.rekeszTipusId=z.alapertelmezettRekeszTipusId;if(id)betoltArak(Number(id))})
const napCim=computed(()=>datum.value===today()?'Mai eladások':`${fmtDate(datum.value)} eladásai`)
const displayBlocks=computed(()=>{const blocks=[];const ix=new Map();for(const item of items.value){if(item.vevoId){if(ix.has(item.vevoId))blocks[ix.get(item.vevoId)].items.push(item);else{ix.set(item.vevoId,blocks.length);blocks.push({vevoId:item.vevoId,vevoNev:item.vevoNev,items:[item]})}}else blocks.push({vevoId:null,vevoNev:null,items:[item]})}return blocks.map(b=>({...b,grouped:b.vevoId!==null&&b.items.length>1}))})
function itemTartozasFt(i){return i.fizetve?0:(i.egysegar!=null?i.mennyiseg*Number(i.egysegar):0)}
function hiany(i){return i.mennyiseg-i.visszahozottDb}
function groupTartozasFt(b){return b.items.reduce((s,i)=>s+itemTartozasFt(i),0)}
function rekeszKey(i){return String(i.rekeszTipusId??i.rekeszTipus??'')}
function groupRekeszTartozasok(b){const map=new Map();for(const i of b.items){const db=Math.max(0,hiany(i)-(i.hianyFizettDb||0));if(db<=0)continue;const key=rekeszKey(i);if(!map.has(key))map.set(key,{key,rekeszTipusId:i.rekeszTipusId??null,rekeszTipus:i.rekeszTipus||'(ismeretlen)',db:0});map.get(key).db+=db}return [...map.values()].sort((a,b)=>a.rekeszTipus.localeCompare(b.rekeszTipus,'hu'))}
function groupRekeszTartozas(b){return groupRekeszTartozasok(b).reduce((s,x)=>s+x.db,0)}
function vhRekesz(i){return i.visszahozottDb===i.mennyiseg}
async function allapot(i,mezo,ertek){try{await client.patch(`/eladas/${i.id}/allapot`,{[mezo]:ertek});i[mezo]=ertek}catch(e){hiba.value=e.response?.data?.message||'Állapotváltás sikertelen.';await frissit()}}
async function vhRekeszValt(i,checked){if(checked){await allapot(i,'visszahozottDb',i.mennyiseg);if(i.hianyFizettDb>0)await allapot(i,'hianyFizettDb',0)}else await allapot(i,'visszahozottDb',0)}
async function csoportMindFizetve(b){for(const i of b.items.filter(x=>!x.fizetve))await allapot(i,'fizetve',true)}
async function csoportMindenRekeszHozott(b,tipusId){for(const i of b.items.filter(x=>rekeszKey(x)===String(tipusId)))if(!vhRekesz(i))await vhRekeszValt(i,true)}
function nyitEladas(stock){selectedStock.value=stock;form.value={vevoId:'',zoldsegId:stock.zoldsegId,rekeszTipusId:stock.rekeszTipusId,mennyiseg:1,egysegar:'',fizetve:false,elvitte:false,visszahozottDb:0,hianyFizettDb:0,megjegyzes:''};betoltArak(stock.zoldsegId);showEladasModal.value=true}
function zarEladas(){showEladasModal.value=false;selectedStock.value=null;arSzerkesztes.value=false}
async function ujTetel(){hiba.value='';if(!form.value.zoldsegId||!form.value.rekeszTipusId)return hiba.value='Zöldség és rekesztípus kiválasztása kötelező.';if(!form.value.mennyiseg||Number(form.value.mennyiseg)<=0)return hiba.value='A mennyiség legalább 1 kell legyen.';if(form.value.egysegar===''||Number(form.value.egysegar)<=0)return hiba.value='Az egységár megadása kötelező.';if(selectedStock.value&&Number(form.value.mennyiseg)>Number(selectedStock.value.kocsinMaradt))return hiba.value='Nem adható el több, mint amennyi a kocsin van.';if(Number(form.value.visszahozottDb)>Number(form.value.mennyiseg))return hiba.value='A visszahozott rekesz nem lehet több az eladott mennyiségnél.';try{await client.post('/eladas',{vevoId:form.value.vevoId||null,ujVevoNev:null,ujVevoMegjegyzes:null,zoldsegId:Number(form.value.zoldsegId),rekeszTipusId:Number(form.value.rekeszTipusId),mennyiseg:Number(form.value.mennyiseg),egysegar:Number(form.value.egysegar),fizetve:form.value.fizetve,elvitte:form.value.elvitte,visszahozottDb:Number(form.value.visszahozottDb)||0,hianyFizettDb:Number(form.value.hianyFizettDb)||0,megjegyzes:form.value.megjegyzes.trim()||null,datum:datum.value});zarEladas();await frissit()}catch(e){hiba.value=e.response?.data?.message||'Mentés sikertelen.'}}
function nyitDetail(i){detailItem.value=i;editId.value=null;editField.value=null;showDetailModal.value=true}
function zarDetail(){showDetailModal.value=false;detailItem.value=null;editId.value=null;editField.value=null}
function szerkesztesInditasa(i){editId.value=i.id;editField.value=null;editForm.value={vevoId:i.vevoId||'',zoldsegId:i.zoldsegId,rekeszTipusId:i.rekeszTipusId,mennyiseg:i.mennyiseg,egysegar:i.egysegar??'',fizetve:i.fizetve,elvitte:i.elvitte,visszahozottDb:i.visszahozottDb,hianyFizettDb:i.hianyFizettDb,megjegyzes:i.megjegyzes||''}}
function mezoSzerkesztesInditasa(i,mezo){detailItem.value=i;editField.value=mezo;editForm.value={vevoId:i.vevoId||'',zoldsegId:i.zoldsegId,rekeszTipusId:i.rekeszTipusId,mennyiseg:i.mennyiseg,egysegar:i.egysegar??'',fizetve:i.fizetve,elvitte:i.elvitte,visszahozottDb:i.visszahozottDb,hianyFizettDb:i.hianyFizettDb,megjegyzes:i.megjegyzes||''}}
function megseMezoSzerkesztes(){editField.value=null}
async function mentMezoSzerkesztes(id){hiba.value='';try{await client.put(`/eladas/${id}`,{vevoId:editForm.value.vevoId||null,ujVevoNev:null,ujVevoMegjegyzes:null,zoldsegId:Number(editForm.value.zoldsegId),rekeszTipusId:Number(editForm.value.rekeszTipusId),mennyiseg:Number(editForm.value.mennyiseg),egysegar:editForm.value.egysegar===''?null:Number(editForm.value.egysegar),fizetve:editForm.value.fizetve,elvitte:editForm.value.elvitte,visszahozottDb:Number(editForm.value.visszahozottDb)||0,hianyFizettDb:Number(editForm.value.hianyFizettDb)||0,megjegyzes:editForm.value.megjegyzes.trim()||null,datum:datum.value});editField.value=null;await frissit();const fresh=items.value.find(x=>x.id===id);if(fresh)detailItem.value=fresh}catch(e){hiba.value=e.response?.data?.message||'Mentés sikertelen.'}}
async function mentSzerkesztes(id){await mentMezoSzerkesztes(id);editId.value=null}
async function modositasokMenteseEsZarasa(){if(editField.value&&detailItem.value){await mentMezoSzerkesztes(detailItem.value.id)}zarDetail()}
async function torol(i){if(!confirm(`Törlöd a #${i.napiSorszam} tételt (${i.zoldsegNev})?`))return;try{await client.delete(`/eladas/${i.id}`);zarDetail();await frissit()}catch{hiba.value='Törlés sikertelen.'}}
function nyitAtvitel(stock){atvitelStock.value=stock;atvitelForm.value={celDatum:holnap(datum.value),mennyiseg:stock.kocsinMaradt};atvitelHiba.value='';showAtvitelModal.value=true}
function zarAtvitel(){showAtvitelModal.value=false;atvitelStock.value=null}
async function mentAtvitel(){atvitelHiba.value='';if(!atvitelForm.value.celDatum)return atvitelHiba.value='Válaszd ki a célnapot.';if(!atvitelForm.value.mennyiseg||Number(atvitelForm.value.mennyiseg)<=0)return atvitelHiba.value='A mennyiség legalább 1 kell legyen.';try{await client.post('/felvasarlas/atvitel',{zoldsegId:atvitelStock.value.zoldsegId,rekeszTipusId:atvitelStock.value.rekeszTipusId,mennyiseg:Number(atvitelForm.value.mennyiseg),celDatum:atvitelForm.value.celDatum});zarAtvitel();await frissit()}catch(e){atvitelHiba.value=e.response?.data?.message||'Átvitel sikertelen.'}}
</script>

<template>
<div class="toolbar"><div class="toolbar-row"><label class="date-picker">📅 Dátum<input v-model="datum" type="date"/></label><label class="search">🔎 Keresés<input v-model="keres" placeholder="Vevő neve, napi sorszám vagy zöldség"/></label></div></div>
<section class="card stock-card"><div class="section-head"><div><h2>Kocsin lévő termékek</h2><p class="muted">Válassz egy terméket az eladás rögzítéséhez, vagy vidd át másnapra.</p></div><span v-if="datum!==today()" class="date-badge">{{fmtDate(datum)}}</span></div><p v-if="betolt">Betöltés…</p><div v-else class="stock-grid"><div v-for="s in keszlet" :key="`${s.zoldsegId}-${s.rekeszTipusId}`" class="stock-tile"><button class="stock-tile-main" type="button" @click="nyitEladas(s)"><div class="stock-tile-photo" :style="csempeStilus(s)"><span class="stock-tile-strip"><strong>{{s.zoldsegNev}}</strong><span>{{s.kocsinMaradt}}</span></span></div></button><button class="stock-tile-atvitel" type="button" @click="nyitAtvitel(s)">📅 Átviszem másnapra</button></div><div v-if="!keszlet.length" class="empty-stock">A kiválasztott napra nincs kocsin maradt áru.</div></div></section>
<section class="card history-card"><div class="section-head"><h2>{{napCim}}</h2><span class="muted">{{items.length}} találat</span></div><div v-if="betolt">Betöltés…</div><template v-else>
<div class="table-wrap desktop-only"><table><thead><tr><th>Vevő</th><th>Zöldség</th><th>Ár</th><th>Db</th><th>Fiz.</th><th>Elv.</th><th>Vh. rek.</th><th>Vissza</th><th>Hiány fiz.</th><th>Tartozás</th><th>Idő</th><th>#</th><th></th></tr></thead><tbody>
<template v-for="block in displayBlocks" :key="'d'+block.items[0].id"><tr v-if="block.grouped" class="group-header-row"><td colspan="13"><div class="group-header"><strong>{{block.vevoNev||'(névtelen)'}}</strong><div class="group-badges"><span v-if="groupTartozasFt(block)>0" class="badge warn">Tartozás: {{groupTartozasFt(block)}} Ft</span><template v-for="rt in groupRekeszTartozasok(block)" :key="'d-rt-'+rt.key"><span class="badge warn">{{rt.db}} {{rt.rekeszTipus}} rekesz tartozás</span></template><span v-if="!groupTartozasFt(block)&&!groupRekeszTartozas(block)" class="badge ok">Rendezve</span></div><div class="group-actions"><button v-if="groupTartozasFt(block)>0" class="link-btn" type="button" @click="csoportMindFizetve(block)">✅ Mind fizetve</button><button v-for="rt in groupRekeszTartozasok(block)" :key="'d-action-'+rt.key" class="link-btn" type="button" @click="csoportMindenRekeszHozott(block,rt.key)">✅ Minden {{rt.rekeszTipus}} hozott</button></div></div></td></tr>
<tr v-for="item in block.items" :key="item.id"><template v-if="editId===item.id"><td><select v-model="editForm.vevoId"><option value="">— alkalmi —</option><option v-for="v in vevek" :key="v.id" :value="v.id">{{vevoCimke(v)}}</option></select></td><td><select v-model="editForm.zoldsegId"><option v-for="z in zoldsegek" :key="z.id" :value="z.id">{{z.nev}}</option></select></td><td><input class="price-input" v-model="editForm.egysegar" type="number" min="0"/></td><td><input v-model="editForm.mennyiseg" type="number" min="1"/></td><td><input v-model="editForm.fizetve" type="checkbox"/></td><td><input v-model="editForm.elvitte" type="checkbox"/></td><td><input :checked="editForm.visszahozottDb===editForm.mennyiseg" @change="editForm.visszahozottDb=$event.target.checked?editForm.mennyiseg:0" type="checkbox"/></td><td><input v-model="editForm.visszahozottDb" type="number" min="0" :max="editForm.mennyiseg" :disabled="editForm.visszahozottDb===editForm.mennyiseg"/></td><td><input v-model="editForm.hianyFizettDb" type="number" min="0" :max="Math.max(0,editForm.mennyiseg-editForm.visszahozottDb)"/></td><td>—</td><td>{{fmtIdo(item.ido)}}</td><td>#{{item.napiSorszam}}</td><td><button class="icon" type="button" @click="mentSzerkesztes(item.id)">✓</button><button class="icon" type="button" @click="editId=null">✕</button></td></template><template v-else><td>{{item.vevoNev||'(névtelen)'}}</td><td>{{item.zoldsegNev}}</td><td>{{item.egysegar!=null?item.egysegar+' Ft':'—'}}</td><td>{{item.mennyiseg}} <small class="muted">{{item.rekeszTipus}}</small></td><td><input type="checkbox" :checked="item.fizetve" @change="allapot(item,'fizetve',$event.target.checked)"/></td><td><input type="checkbox" :checked="item.elvitte" @change="allapot(item,'elvitte',$event.target.checked)"/></td><td><input type="checkbox" :checked="vhRekesz(item)" @change="vhRekeszValt(item,$event.target.checked)"/></td><td><input type="number" min="0" :max="item.mennyiseg" :value="item.visszahozottDb" :disabled="vhRekesz(item)" @change="allapot(item,'visszahozottDb',Number($event.target.value))"/></td><td><input type="number" min="0" :max="hiany(item)" :value="item.hianyFizettDb" @change="allapot(item,'hianyFizettDb',Number($event.target.value))"/></td><td><span v-if="itemTartozasFt(item)>0" class="badge warn">{{itemTartozasFt(item)}} Ft</span><span v-if="hiany(item)-Number(item.hianyFizettDb||0)>0" class="badge warn">{{hiany(item)-Number(item.hianyFizettDb||0)}} rekesz</span><span v-if="!itemTartozasFt(item)&&hiany(item)-Number(item.hianyFizettDb||0)<=0" class="badge ok">Rendezve</span></td><td>{{fmtIdo(item.ido)}}</td><td>#{{item.napiSorszam}}</td><td><button class="icon" type="button" @click="szerkesztesInditasa(item)">✏️</button><button class="icon" type="button" @click="torol(item)">🗑️</button></td></template></tr></template><tr v-if="!items.length"><td colspan="13" class="ures">Nincs a keresésnek megfelelő eladás.</td></tr></tbody></table></div>
<div class="mobile-list mobile-only"><template v-for="block in displayBlocks" :key="'m'+block.items[0].id"><div v-if="block.grouped" class="group-frame"><div class="group-header"><strong>{{block.vevoNev||'(névtelen)'}}</strong><div class="group-badges"><span v-if="groupTartozasFt(block)>0" class="badge warn">Tartozás: {{groupTartozasFt(block)}} Ft</span><template v-for="rt in groupRekeszTartozasok(block)" :key="'m-rt-'+rt.key"><span class="badge warn">{{rt.db}} {{rt.rekeszTipus}} rekesz</span></template></div><div class="group-actions"><button v-if="groupTartozasFt(block)>0" class="link-btn" type="button" @click="csoportMindFizetve(block)">✅ Mind fizetve</button><button v-for="rt in groupRekeszTartozasok(block)" :key="'m-action-'+rt.key" class="link-btn" type="button" @click="csoportMindenRekeszHozott(block,rt.key)">✅ Minden {{rt.rekeszTipus}} hozott</button></div></div><button v-for="item in block.items" :key="item.id" class="mobile-tile grouped-tile" type="button" @click="nyitDetail(item)"><div class="mobile-tile-row"><span class="zoldseg-nev"><img v-if="zoldsegKep(item.zoldsegId)" :src="zoldsegKep(item.zoldsegId)" class="mini-thumb" alt=""/>{{item.zoldsegNev}}</span><span class="mobile-tile-time">{{fmtIdo(item.ido)}}</span></div><div class="mobile-tile-row"><span>{{item.mennyiseg}} {{item.rekeszTipus}}</span><span>{{item.egysegar!=null?item.egysegar+' Ft':'—'}}</span></div><div class="mobile-tile-badges"><span :class="['badge',item.fizetve?'ok':'nok']">{{item.fizetve?'Fizetve':'Nincs fizetve'}}</span><span :class="['badge',item.elvitte?'ok':'nok']">{{item.elvitte?'Elvitte':'Nem vitte el'}}</span><span v-if="itemTartozasFt(item)>0" class="badge warn">Tartozás: {{itemTartozasFt(item)}} Ft</span><span v-if="hiany(item)-Number(item.hianyFizettDb||0)>0" class="badge warn">{{hiany(item)-Number(item.hianyFizettDb||0)}} {{item.rekeszTipus}} rekesz tartozás</span><span v-if="itemTartozasFt(item)===0&&hiany(item)-Number(item.hianyFizettDb||0)<=0" class="badge ok">Rendezve</span></div></button></div><button v-else class="mobile-tile" type="button" @click="nyitDetail(block.items[0])"><div class="mobile-tile-row"><strong>{{block.items[0].vevoNev||'(névtelen)'}}</strong><span class="mobile-tile-time">{{fmtIdo(block.items[0].ido)}}</span></div><div class="mobile-tile-row"><span class="zoldseg-nev"><img v-if="zoldsegKep(block.items[0].zoldsegId)" :src="zoldsegKep(block.items[0].zoldsegId)" class="mini-thumb" alt=""/>{{block.items[0].zoldsegNev}}</span><span>{{block.items[0].mennyiseg}} {{block.items[0].rekeszTipus}}</span></div><div class="mobile-tile-badges"><span :class="['badge',block.items[0].fizetve?'ok':'nok']">{{block.items[0].fizetve?'Fizetve':'Nincs fizetve'}}</span><span :class="['badge',block.items[0].elvitte?'ok':'nok']">{{block.items[0].elvitte?'Elvitte':'Nem vitte el'}}</span><span v-if="itemTartozasFt(block.items[0])>0" class="badge warn">Tartozás: {{itemTartozasFt(block.items[0])}} Ft</span><span v-if="hiany(block.items[0])-Number(block.items[0].hianyFizettDb||0)>0" class="badge warn">{{hiany(block.items[0])-Number(block.items[0].hianyFizettDb||0)}} {{block.items[0].rekeszTipus}} rekesz tartozás</span><span v-if="itemTartozasFt(block.items[0])===0&&hiany(block.items[0])-Number(block.items[0].hianyFizettDb||0)<=0" class="badge ok">Rendezve</span></div></button></template><div v-if="!items.length" class="empty-stock">Nincs a keresésnek megfelelő eladás.</div></div></template></section>

<div v-if="showEladasModal" class="overlay" @click.self="zarEladas"><div class="sale-modal card"><div class="modal-head"><div><h2>{{selectedStock?.zoldsegNev}} — eladás</h2><div class="stock-info">Kocsin: <strong>{{selectedStock?.kocsinMaradt}}</strong> {{selectedStock?.rekeszTipus}}</div></div><button class="icon close" type="button" @click="zarEladas">✕</button></div><label>Vevő (opcionális)<Gyorskereso v-model="form.vevoId" :items="vevek" post-path="/vevek" mentes-label="Vevő mentése" placeholder="Üresen hagyva alkalmi vevő" @created="vevoLetrehozva"/></label><div class="row"><label>Mennyit vett<input :value="form.mennyiseg" @input="form.mennyiseg=clampDigits($event.target.value,3)" inputmode="numeric" class="narrow-3"/></label><label>Egységár (Ft/db)<input :value="form.egysegar" @input="form.egysegar=clampDigits($event.target.value,5)" inputmode="numeric" class="narrow-5"/></label></div><div class="quick-price"><div class="quick-price-head"><span>Gyorsárak</span><button type="button" class="pencil" :class="{active:arSzerkesztes}" @click="arSzerkesztes?mentesArak():arSzerkesztes=true">{{arSzerkesztes?'✓':'✏️'}}</button></div><div class="quick-buttons"><template v-for="(ar,i) in gyorsArak" :key="i"><input v-if="arSzerkesztes" v-model="gyorsArak[i]" class="quick-input" inputmode="numeric" maxlength="5" placeholder="Ft/db"/><button v-else type="button" class="quick-btn" :disabled="ar===''" @click="gyorsArBeallit(ar)">{{ar===''?'—':Number(ar)+' Ft'}}</button></template></div><small v-if="arSzerkesztes" class="quick-hint">A három érték ennél a zöldségnél, ezen a böngészőn kerül elmentésre.</small></div><div class="row"><button type="button" class="toggle-pill" :class="{active:form.fizetve}" @click="form.fizetve=!form.fizetve">{{form.fizetve?'✅ Fizette':'⬜ Fizette'}}</button><button type="button" class="toggle-pill" :class="{active:form.elvitte}" @click="form.elvitte=!form.elvitte">{{form.elvitte?'✅ Elvitte':'⬜ Elvitte'}}</button></div><button type="button" class="toggle-pill wide" :class="{active:form.visszahozottDb===Number(form.mennyiseg)&&form.mennyiseg!==''}" @click="form.visszahozottDb=(form.visszahozottDb===Number(form.mennyiseg)?0:Number(form.mennyiseg))">{{form.visszahozottDb===Number(form.mennyiseg)&&form.mennyiseg!==''?'✅ Minden rekeszt hozott':'⬜ Minden rekeszt hozott'}}</button><div class="row"><label>Rekeszt hozott<input :value="form.visszahozottDb" @input="form.visszahozottDb=clampDigits($event.target.value,3)" inputmode="numeric" class="narrow-3" :disabled="form.visszahozottDb===Number(form.mennyiseg)&&form.mennyiseg!==''"/></label><label>Hiányból kifizetett (db)<input :value="form.hianyFizettDb" @input="form.hianyFizettDb=clampDigits($event.target.value,3)" inputmode="numeric" class="narrow-3"/></label></div><label>Megjegyzés (opcionális)<input v-model="form.megjegyzes" placeholder="pl. később jön az áruért"/></label><p v-if="hiba" class="hiba">{{hiba}}</p><button class="btn-primary save" type="button" @click="ujTetel">Eladás mentése</button></div></div>

<div v-if="showDetailModal&&detailItem" class="overlay" @click.self="zarDetail"><div class="sale-modal card"><div class="modal-head"><div><h2>{{detailItem.zoldsegNev}} — #{{detailItem.napiSorszam}}</h2><div class="stock-info">{{fmtIdo(detailItem.ido)}} · {{detailItem.vevoNev||'(névtelen)'}}</div></div><button class="icon close" type="button" @click="zarDetail">✕</button></div>
<div class="detail-rows">
<div class="detail-row"><span class="detail-row-label">Zöldség</span><template v-if="editField==='zoldseg'"><select v-model="editForm.zoldsegId"><option v-for="z in zoldsegek" :key="z.id" :value="z.id">{{z.nev}}</option></select></template><strong v-else>{{detailItem.zoldsegNev}}</strong><div class="detail-row-actions"><button v-if="editField!=='zoldseg'" class="icon pencil-row" type="button" @click="mezoSzerkesztesInditasa(detailItem,'zoldseg')">✏️</button><template v-else><button class="icon row-save" type="button" @click="mentMezoSzerkesztes(detailItem.id)">✓</button><button class="icon row-cancel" type="button" @click="megseMezoSzerkesztes">✕</button></template></div></div>
<div class="detail-row"><span class="detail-row-label">Mennyiség</span><template v-if="editField==='mennyiseg'"><input v-model="editForm.mennyiseg" type="number" min="1"/></template><strong v-else>{{detailItem.mennyiseg}} {{detailItem.rekeszTipus}}</strong><div class="detail-row-actions"><button v-if="editField!=='mennyiseg'" class="icon pencil-row" type="button" @click="mezoSzerkesztesInditasa(detailItem,'mennyiseg')">✏️</button><template v-else><button class="icon row-save" type="button" @click="mentMezoSzerkesztes(detailItem.id)">✓</button><button class="icon row-cancel" type="button" @click="megseMezoSzerkesztes">✕</button></template></div></div>
<div class="detail-row"><span class="detail-row-label">Ár</span><template v-if="editField==='ar'"><input v-model="editForm.egysegar" type="number" min="0" placeholder="Ft/db"/></template><strong v-else>{{detailItem.egysegar!=null?detailItem.egysegar+' Ft':'—'}}</strong><div class="detail-row-actions"><button v-if="editField!=='ar'" class="icon pencil-row" type="button" @click="mezoSzerkesztesInditasa(detailItem,'ar')">✏️</button><template v-else><button class="icon row-save" type="button" @click="mentMezoSzerkesztes(detailItem.id)">✓</button><button class="icon row-cancel" type="button" @click="megseMezoSzerkesztes">✕</button></template></div></div>
<div class="detail-row"><span class="detail-row-label">Vevő</span><template v-if="editField==='vevo'"><select v-model="editForm.vevoId"><option value="">— alkalmi vevő —</option><option v-for="v in vevek" :key="v.id" :value="v.id">{{vevoCimke(v)}}</option></select></template><strong v-else>{{detailItem.vevoNev||'(alkalmi)'}}</strong><div class="detail-row-actions"><button v-if="editField!=='vevo'" class="icon pencil-row" type="button" @click="mezoSzerkesztesInditasa(detailItem,'vevo')">✏️</button><template v-else><button class="icon row-save" type="button" @click="mentMezoSzerkesztes(detailItem.id)">✓</button><button class="icon row-cancel" type="button" @click="megseMezoSzerkesztes">✕</button></template></div></div>
</div>
<label class="checkbox"><input type="checkbox" :checked="detailItem.fizetve" @change="allapot(detailItem,'fizetve',$event.target.checked)"/> Fizetve</label><label class="checkbox"><input type="checkbox" :checked="detailItem.elvitte" @change="allapot(detailItem,'elvitte',$event.target.checked)"/> Elvitte</label><label class="checkbox"><input type="checkbox" :checked="vhRekesz(detailItem)" @change="vhRekeszValt(detailItem,$event.target.checked)"/> Minden rekeszt hozott</label><label>Visszahozott rekesz<input type="number" min="0" :max="detailItem.mennyiseg" :value="detailItem.visszahozottDb" @change="allapot(detailItem,'visszahozottDb',Number($event.target.value))"/></label><label>Hiányzó rekeszből kifizetett (db)<input type="number" min="0" :max="hiany(detailItem)" :value="detailItem.hianyFizettDb" @change="allapot(detailItem,'hianyFizettDb',Number($event.target.value))"/></label><div class="nav-row"><button class="btn-primary" type="button" @click="modositasokMenteseEsZarasa">✅ Mentés</button><button class="btn-secondary danger-btn" type="button" @click="torol(detailItem)">🗑️ Töröl</button></div><p v-if="hiba" class="hiba">{{hiba}}</p></div></div>

<div v-if="showAtvitelModal" class="overlay" @click.self="zarAtvitel"><div class="sale-modal card"><div class="modal-head"><h2>{{atvitelStock?.zoldsegNev}} átvitele</h2><button class="icon close" type="button" @click="zarAtvitel">✕</button></div><label>Célnap<input v-model="atvitelForm.celDatum" type="date"/></label><label>Átvitt mennyiség<input v-model="atvitelForm.mennyiseg" type="number" min="1"/></label><p v-if="atvitelHiba" class="hiba">{{atvitelHiba}}</p><button class="btn-primary save" type="button" @click="mentAtvitel">Átvitel mentése</button></div></div>
